properties.command:
ls ~/.claude/projects/<project>/*.jsonl 2>/dev/null | head; T=$(ls -t ~/.claude/projects/<project>/*.jsonl 2>/dev/null | head -1); echo "TRANSCRIPT: $T"; python3 -c "
import json,sys
path='$T'
kinds={}
usage_sample=None
cost=0.0; seen_cost=False
with open(path) as f:
    for line in f:
        try: e=json.loads(line)
        except: continue
        t=e.get('type'); kinds[t]=kinds.get(t,0)+1
        if t=='assistant':
            m=e.get('message') or {}
            u=m.get('usage')
            if u and not usage_sample: usage_sample={'usage':u,'model':m.get('model'),'keys':sorted(e.keys())}
        if 'costUSD' in e: seen_cost=True; cost+=e.get('costUSD') or 0
print('kinds:',kinds)
print('sample:',json.dumps(usage_sample,indent=1)[:900])
print('costUSD present:',seen_cost, cost)
"

grep 'nonexistent/hindsight-test' .hindsight/events/*.jsonl | head -c 700; echo; python3 -c "
import json
path='~/.claude/projects/<project>/ad10c137-34a8-42f7-88c5-ef305a40a6f9.jsonl'
for line in open(path):
    try: e=json.loads(line)
    except: continue
    if e.get('type')=='user':
        m=e.get('message') or {}
        c=m.get('content')
        if isinstance(c,list):
            for b in c:
                if isinstance(b,dict) and b.get('type')=='tool_result' and b.get('is_error'):
                    print('TOOL_RESULT is_error sample keys:', sorted(b.keys()))
                    print(json.dumps(b)[:400]); break
"
